import { Box, Paper, Typography, Stack, Chip, CircularProgress, Button, IconButton, Tooltip } from "@mui/material"
import RefreshIcon from "@mui/icons-material/Refresh"
import GameTimer from "../timer"
import usePublicRooms from "../../hooks/publicRooms"
import { LOBBY_TTL } from "../../helper/ttls"

export default function PublicRoomsList({ onClick = () => {} }) {

  const {
    rooms,
    activeRooms,
    activePlayers,
    loading,
    loadingMore,
    hasMore,
    refresh,
    loadMore,
    removeRoom,
  } = usePublicRooms()

  // -------------------------
  // LOADING
  // -------------------------
  if (loading) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="100%"
        sx={{ px: 4 }}
      >
        <Paper
          elevation={8}
          sx={{
            width: "100%",
            maxWidth: 700,
            p: 5,
            borderRadius: 5,
            overflow: "hidden",
            position: "relative",
            bgcolor: "transparent",
            color: "var(--whueo-hex_ffffff)",
            border: "3px solid var(--whueo-hex_374151)",
            backdropFilter: "blur(10px)",
          }}
        >
          <Box
            sx={{
              position: "absolute",
              width: 320,
              height: 320,
              borderRadius: "50%",
              bgcolor: "var(--whueo-rgba_33_150_243_0p14)",
              filter: "blur(120px)",
              top: -150,
              right: -120,
              pointerEvents: "none",
            }}
          />
          <Stack spacing={2} alignItems="center" position="relative" zIndex={2}>
            <CircularProgress size={60} />
            <Typography variant="h6" fontWeight={700}>
              Loading Public Rooms...
            </Typography>
            <Typography variant="body2" color="var(--whueo-hex_888888)">
              Fetching active players and rooms
            </Typography>
          </Stack>
        </Paper>
      </Box>
    )
  }

  // -------------------------
  // EMPTY
  // -------------------------
  if (!rooms.length) {
    return (
      <Box
        display="flex"
        justifyContent="center"
        alignItems="center"
        minHeight="100%"
        bgcolor="brand.dark"
        sx={{ px: 4 }}
      >
        <Paper
          elevation={8}
          sx={{
            width: "100%",
            maxWidth: 700,
            p: 5,
            borderRadius: 5,
            overflow: "hidden",
            position: "relative",
            bgcolor: "transparent",
            color: "var(--whueo-hex_ffffff)",
            border: "3px solid var(--whueo-hex_374151)",
          }}
        >
          <Box
            sx={{
              position: "absolute",
              width: 320,
              height: 320,
              borderRadius: "50%",
              bgcolor: "var(--whueo-rgba_255_255_255_0p05)",
              filter: "blur(120px)",
              top: -150,
              right: -120,
              pointerEvents: "none",
            }}
          />
          <Stack spacing={2} alignItems="center" position="relative" zIndex={2}>
            <Box
              sx={{
                width: 90,
                height: 90,
                borderRadius: "50%",
                bgcolor: "var(--whueo-rgba_255_255_255_0p05)",
                border: "1px solid var(--whueo-hex_3f3f46)",
                display: "flex",
                justifyContent: "center",
                alignItems: "center",
                fontSize: 40,
              }}
            >
              🎮
            </Box>
            <Typography variant="h5" fontWeight={800}>
              No Public Rooms
            </Typography>
            <Typography color="var(--whueo-hex_888888)" textAlign="center" maxWidth={400}>
              Looks quiet right now. Create a room and become the first squad online.
            </Typography>
            <Button
              variant="outlined"
              onClick={refresh}
              startIcon={<RefreshIcon />}
              sx={{
                mt: 1,
                borderRadius: 2,
                textTransform: "none",
                fontWeight: 600,
                borderColor: "var(--whueo-hex_374151)",
                color: "var(--whueo-hex_888888)",
                "&:hover": { borderColor: "var(--whueo-hex_15ff00)", color: "var(--whueo-hex_15ff00)" },
              }}
            >
              Refresh
            </Button>
          </Stack>
        </Paper>
      </Box>
    )
  }

  // -------------------------
  // UI
  // -------------------------
  return (
    <Box
      sx={{
        height: "100%",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        px: 4,
        // py: 1
      }}
    >
      <Stack
  spacing={3}
  position="relative"
  zIndex={2}
  sx={{
    flex: 1,
    minHeight: 0,
    width: "100%",
    maxWidth: 700,
    maxHeight: "90%",
  }}
>
  {/* HEADER */}
  <Box
    display="flex"
    justifyContent="space-between"
    alignItems={{ xs: "flex-start", sm: "center" }}
    // flexDirection={{ xs: "column", sm: "row" }}
    flexDirection={"row"}
    gap={2}
  >
    <Box>
      <Stack direction="row" spacing={1} alignItems="center">
        <Typography variant="h4" color="var(--whueo-hex_ffffff)" fontWeight={900}>
          Public Rooms
        </Typography>
        <Tooltip title="Refresh rooms">
          <IconButton
            onClick={refresh}
            size="small"
            sx={{
              color: "var(--whueo-hex_888888)",
              "&:hover": { color: "var(--whueo-hex_15ff00)" },
            }}
          >
            <RefreshIcon fontSize="small" />
          </IconButton>
        </Tooltip>
      </Stack>

      <Typography variant="body2" color="var(--whueo-hex_888888)">
        Join active games happening right now
      </Typography>
    </Box>

    {/* STATS */}
    <Stack
      direction={{ xs: "column", sm: "row" }}
      spacing={2}
      width={{ xs: "100%", sm: "auto" }}
    >
      <Paper
        sx={{
          px: 2,
          py: 1.2,
          bgcolor: "var(--whueo-rgba_255_255_255_0p04)",
          border: "1px solid var(--whueo-hex_2f2f2f)",
          borderRadius: 3,
        }}
      >
        <Stack direction="row" spacing={1} alignItems="center">
          <Typography fontSize={22}>🏠</Typography>
          <Box>
            <Typography fontWeight={800} lineHeight={1}>
              {activeRooms}
            </Typography>
            <Typography variant="caption" color="var(--whueo-hex_888888)">
              Active Rooms
            </Typography>
          </Box>
        </Stack>
      </Paper>

      <Paper
        sx={{
          px: 2,
          py: 1.2,
          bgcolor: "var(--whueo-rgba_255_255_255_0p04)",
          border: "1px solid var(--whueo-hex_2f2f2f)",
          borderRadius: 3,
        }}
      >
        <Stack direction="row" spacing={1} alignItems="center">
          <Typography fontSize={22}>👥</Typography>
          <Box>
            <Typography fontWeight={800} lineHeight={1}>
              {activePlayers}
            </Typography>
            <Typography variant="caption" color="var(--whueo-hex_888888)">
              Players Online
            </Typography>
          </Box>
        </Stack>
      </Paper>
    </Stack>
  </Box>

  {/* SCROLLABLE ROOM LIST */}
  <Box
    sx={{
      flex: 1,
      overflowY: "auto",
      pr: 1,
      minHeight: 0,
    }}
  >
    <Stack spacing={1.5}>
      {rooms.map((room) => (
        <Paper
          key={room.roomId}
          onClick={() => onClick(room)}
          sx={{
            p: 2.2,
            cursor: "pointer",
            position: "relative",
            overflow: "hidden",
            bgcolor: "var(--whueo-rgba_255_255_255_0p03)",
            border: "1px solid var(--whueo-hex_262626)",
            borderRadius: 4,
            transition: "all 0.25s ease",
            "&:hover": {
              borderColor: "brand.light",
              transform: "translateY(-3px)",
              bgcolor: "var(--whueo-rgba_255_255_255_0p05)",
              boxShadow: "0 10px 30px var(--whueo-rgba_21_255_0_0p12)",
            },
          }}
        >
          <Box
            sx={{
              position: "absolute",
              width: 180,
              height: 180,
              borderRadius: "50%",
              bgcolor: "var(--whueo-rgba_21_255_0_0p12)",
              filter: "blur(80px)",
              top: -80,
              right: -60,
              pointerEvents: "none",
            }}
          />

          <Box
            display="flex"
            justifyContent="space-between"
            alignItems="center"
            position="relative"
            zIndex={2}
          >
            <Box>
              <Stack direction="row" spacing={1} alignItems="center">
                <Typography variant="h6" fontWeight={800}>
                  {room.roomId}
                </Typography>

                {room.private && (
                  <Chip
                    label="Private"
                    size="small"
                    color="error"
                  />
                )}
              </Stack>

              <Stack direction="row" spacing={1} mt={0.7}>
                <Typography variant="body2" color="var(--whueo-hex_9ca3af)">
                  ⏱{" "}
                  <GameTimer
                    startTime={room.created}
                    totalTime={LOBBY_TTL}
                    onFinish={() => removeRoom(room.roomId)}
                  />
                </Typography>
              </Stack>
            </Box>

            <Stack direction="row" spacing={1} alignItems="center">
              <Chip
                size="small"
                label={room.state === "build" ? "Lobby" : "In Game"}
                color={room.state === "build" ? "success" : "warning"}
              />

              <Chip
                size="small"
                label={`👥 ${room.players}/${room.maxPlayers}`}
                color="primary"
              />
            </Stack>
          </Box>
        </Paper>
      ))}
    </Stack>
  </Box>

  {/* LOAD MORE */}
  {hasMore && (
    <Button
      variant="contained"
      onClick={loadMore}
      disabled={loadingMore}
      sx={{
        py: 1.4,
        borderRadius: 3,
        fontWeight: 700,
        textTransform: "none",
        fontSize: 16,
      }}
    >
      {loadingMore ? "Loading More Rooms..." : "Load More Rooms"}
    </Button>
  )}
</Stack>
    </Box>
  )
}